def mixed_inverse_3_1_1_0_1(n):
    low = 0
    high = n + 1
    while low < high:
        mid = (low + high) // 2
        if 1 * mid * mid * mid + 1 * mid * mid + 0 * mid <= 1 * n:
            low = mid + 1
        else:
            high = mid
    return low - 1

